  if(selC) selC.innerHTML=`<option value="">Todas las categorías</option>`+cats.map(c=>`<option value="${c}">${c}</option>`).join("");
  const paises=[...new Set(CAT.map(c=>c.pais).filter(Boolean))].sort(), selP=document.getElementById("fpais");
