      return `<div style="display:flex;align-items:center;padding:10px;border:1px solid var(--border-color);border-radius:8px;cursor:pointer;background:var(--bg-surface)" onclick="mostrarDiseñador('${esc(k)}')">${foto}<div><b>${esc(k)}</b><br><small>${esc(d.nacionalidad||'')} · ${esc(d.periodo||'')}</small></div></div>`;
